(()=>{const $=id=>document.getElementById(id),D=DrawingLanguage,M=DrawingMethods;let subject=new URLSearchParams(location.search).get('subject')||'old-tree',seed=41,mode='finished',method='gesture',tool='brush',notes={},model,timer;if(!M.subjects.some(s=>s.id===subject))subject='old-tree';try{notes=JSON.parse(localStorage.getItem('ranch-drawing-critiques-v1'))||{};}catch{}const key=()=>subject+':'+seed+(method==='current'?'':':'+method+(method==='simulation'?':'+tool:''));
function draw(){const s=M.subjects.find(x=>x.id===subject),m=M.build(subject,seed,method,tool);model=m;clearInterval(timer);timer=null;$('replay-strokes').textContent='Replay strokes';$('stroke-progress').value=100;D.mount($('skeleton'),m,'structure');paint();$('subject-name').textContent=s.name;$('subject-family').textContent=s.family;$('rules').replaceChildren(...s.rules.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));$('next-study').textContent=s.next;$('feedback').value=notes[key()]?.text||'';$('stage-caption').textContent=M.methods[method]+' · '+{structure:'Structure only',wash:'Color wash · local material colors',shade:'Shade · overlap and sheltered planes',ink:'Ink · structural edges and directional marks',finished:'Finished study'}[mode];$('drawing-status').textContent=`${s.name} · seed ${seed} · ${M.methods[method]}`;$('skeleton').setAttribute('aria-label',s.name+' structural skeleton');$('finished').setAttribute('aria-label',s.name+' '+mode+' drawing');$('subjects').value=subject;$('method-description').textContent=M.descriptions[method];$('hand-tool').disabled=method!=='simulation';$('compare-methods').disabled=method==='current';$('method-note').textContent=method==='current'&&!D.subjects.some(s=>s.id===subject)?'New subject: simple baseline rendering of the shared plan.':method==='simulation'?'Simulation controls mark-making; gesture placement is shared with Gesture.':'';document.querySelectorAll('[data-method]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.method===method));syncComparison();window.RanchView?.changed();document.querySelectorAll('[data-layer]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.layer===mode));}
for(const s of M.subjects){const option=document.createElement('option');option.textContent=s.name;option.value=s.id;$('subjects').append(option);}for(const [id,step] of [['previous-subject',-1],['next-subject',1]])$(id).onclick=()=>{const i=M.subjects.findIndex(s=>s.id===subject);subject=M.subjects[(i+step+M.subjects.length)%M.subjects.length].id;draw();};$('subjects').onchange=()=>{subject=$('subjects').value;draw();};function syncComparison(){const show=$('compare-methods').checked&&method!=='current';$('baseline-figure').hidden=!show;document.querySelector('.specimen-pair').classList.toggle('comparing',$('compare').checked);document.querySelector('.specimen-pair').classList.toggle('method-comparing',show);document.querySelector('.specimen-pair').style.setProperty('--study-count',1+Number(show)+Number($('compare').checked));if(show)D.mount($('baseline'),M.build(subject,seed,'current'),mode,+$('stroke-progress').value/100);window.RanchView?.changed();}$('compare').onchange=syncComparison;$('compare-methods').onchange=syncComparison;document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{method=b.dataset.method;draw();});$('hand-tool').onchange=()=>{tool=$('hand-tool').value;draw();};document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{mode=b.dataset.layer;draw();});$('new-seed').onclick=()=>{seed=seed>=999999?1:seed+1;$('drawing-seed').value=seed;draw();};$('drawing-seed').onchange=()=>{seed=Math.max(1,Math.min(999999,Math.round(+$('drawing-seed').value||1)));$('drawing-seed').value=seed;draw();};
function paint(){const info=D.mount($('finished'),model,mode,+$('stroke-progress').value/100);$('stroke-count').textContent=info?`${info.visible} / ${info.count}`:'Guides';$('brush-readout').textContent=info?.last?`${info.last.purpose||D.brushes[info.last.brush].label} · ${info.last.tool||info.last.brush} · ${info.last.layer}`:'Construction paths · choose a painted stage to inspect brush marks';if($('compare-methods').checked&&method!=='current')D.mount($('baseline'),M.build(subject,seed,'current'),mode,+$('stroke-progress').value/100);window.RanchView?.changed();}
$('stroke-progress').oninput=()=>{clearInterval(timer);timer=null;$('replay-strokes').textContent='Replay strokes';paint();};$('replay-strokes').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('replay-strokes').textContent='Replay strokes';return;}$('stroke-progress').value=0;$('replay-strokes').textContent='Pause';paint();timer=setInterval(()=>{$('stroke-progress').value=Math.min(100,+$('stroke-progress').value+1);paint();if(+$('stroke-progress').value===100){clearInterval(timer);timer=null;$('replay-strokes').textContent='Replay strokes';}},90);};
function save(){notes[key()]={subject,seed,method,tool,stage:mode,text:$('feedback').value,updatedAt:new Date().toISOString()};try{localStorage.setItem('ranch-drawing-critiques-v1',JSON.stringify(notes));$('feedback-status').textContent='Saved on this device for '+subject+', seed '+seed+'. Export to share.';}catch{$('feedback-status').textContent='Browser saving unavailable. Export feedback to keep a copy.';}}
$('save-feedback').onclick=save;$('feedback').onchange=save;$('export-feedback').onclick=()=>{save();const u=URL.createObjectURL(new Blob([JSON.stringify({format:'ranch-drawing-critiques-v1',notes},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='drawing-explorer-feedback.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};const drawer=$('illustrator-tools'),toggle=$('tools-toggle'),wide=()=>matchMedia('(min-width:1100px)').matches;
function closeTools(){drawer.close();}
function openTools(){if(wide())drawer.show();else drawer.showModal();document.body.classList.add('tools-open');toggle.setAttribute('aria-expanded','true');$('tools-close').focus();window.RanchView?.changed();}
toggle.onclick=()=>drawer.open?closeTools():openTools();$('tools-close').onclick=closeTools;
drawer.addEventListener('close',()=>{document.body.classList.remove('tools-open');toggle.setAttribute('aria-expanded','false');toggle.focus();window.RanchView?.changed();});
drawer.addEventListener('click',e=>{const r=drawer.getBoundingClientRect();if(e.target===drawer&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))closeTools();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&drawer.open){e.preventDefault();closeTools();}});
matchMedia('(min-width:1100px)').addEventListener('change',()=>{if(drawer.open)closeTools();});
draw();window.RanchView?.register('drawing',()=>({subject,seed,method,tool,compareMethods:$('compare-methods').checked,stage:mode,strokeProgress:+$('stroke-progress').value,comparing:$('compare').checked,toolsOpen:drawer.open}));})();
